import { Component } from '@angular/core';
import { Leave } from '../../models/leave.model';

@Component({
  selector: 'app-leave-application',
  templateUrl: './leave-application.component.html',
  styleUrls: ['./leave-application.component.css']
})
export class LeaveApplicationComponent {
  leave: Leave = {
    employeeId: 1,
    leaveType: '',
    startDate: '',
    endDate: '',
    status: 'Pending' // ✅ Ensure this property exists
  };

  constructor() {}

  applyLeave() {
    console.log("Applying Leave:", this.leave);
  }
}
<h2>Apply for Leave</h2>
<form (ngSubmit)="applyLeave()">
  <label>Leave Type:</label>
  <input type="text" [(ngModel)]="leave.leaveType" name="leaveType" required />

  <label>Start Date:</label>
  <input type="date" [(ngModel)]="leave.startDate" name="startDate" required />

  <label>End Date:</label>
  <input type="date" [(ngModel)]="leave.endDate" name="endDate" required />

  <button type="submit">Apply Leave</button>
</form>
